import { useEffect, useRef, useState, type ReactNode } from 'react'
import { useSearchParams } from 'react-router-dom'
import { Building2, Users, ShieldCheck, Percent, Coins, CreditCard, FileText, Bell, Database, History, DoorOpen, Printer, Search, Plus, Pencil, Ban, Check, Trash2, Download, Upload, RefreshCw, Mail, MessageSquare, AlertTriangle, Settings } from 'lucide-react'
import { BaseLayout } from '@/components/layouts/base-layout'
import { Dialog, DialogContent, DialogDescription, DialogHeader, DialogTitle } from '@/components/ui/dialog'
import { fetchApi, getAccounts, getAccountDirectory, saveAccount, createAccountRole, getCallPolicy, saveCallPolicy } from '@/lib/api'
import { getClinicConfig, saveClinicSection, getClinicSystem, getClinicJournal, createClinicBackup, downloadClinicBackup, downloadCsv, type ClinicConfig, type ClinicSystem, type AuditLog, type Permission } from '@/lib/clinic-settings'
import { useAccountStore, FEATURES, EXAMS, type Account, type AccountRole } from '@/stores/account-store'
import { DEFAULT_ROLE_PERMISSIONS } from '@/stores/role-permissions-store'
import { formatPhoneNumber } from '@/lib/utils'
import { AdminResourceManagement } from './admin-resource-management'
import { toast } from 'sonner'
import { PrinterSettingsPanel } from './printer-settings'
import '@/styles/designs/cima-settings.css'

const primary = 'bg-indigo-600 hover:bg-indigo-700 text-white text-sm font-medium px-4 py-2 rounded-lg transition shadow-sm shadow-indigo-500/30 inline-flex items-center justify-center gap-2'
const secondary = 'bg-white border border-slate-200 hover:bg-slate-50 text-slate-700 text-sm font-medium px-4 py-2 rounded-lg transition inline-flex items-center justify-center gap-2'
const inputClass = 'w-full bg-slate-50 border border-slate-200 rounded-lg px-3 py-2.5 text-sm outline-none focus:ring-2 focus:ring-indigo-500/30 focus:border-indigo-500 transition'
const sections = [
  ['clinic', 'Clinique', Building2], ['users', 'Utilisateurs', Users], ['permissions', 'Rôles & Permissions', ShieldCheck], ['taxes', 'Taxes & TVA', Percent],
  ['currencies', 'Devises', Coins], ['payments', 'Modes de paiement', CreditCard], ['documents', 'Modèles de documents', FileText],
  ['notifications', 'Notifications', Bell], ['security', 'Sauvegarde & Sécurité', Database], ['journal', 'Journal d’activité', History], ['rooms', 'Salles d’examen', DoorOpen],
  ['printers', 'Imprimantes', Printer],
] as const
const modules = [
  ['dashboard', 'Tableau de bord', '/dashboard-2'], ['patients', 'Patients', '/patients'], ['appointments', 'Rendez-vous', '/rendez-vous'], ['queue', 'File d’attente', '/queue-management'],
  ['reports', 'Comptes rendus', '/comptes-rendus'], ['prescriptions', 'Prescriptions', '/comptes-rendus'], ['images', 'Images', '/comptes-rendus'], ['ready_files', 'Dossiers prêts', '/secretariat'],
  ['payments', 'Règlements', '/payments'], ['finance', 'Finance & Comptabilité', '/finance'], ['chat', 'Messagerie interne', '/chat'], ['settings', 'Paramètres', '/settings/user'],
] as const
type AccountDraft = Pick<Account, 'name' | 'email' | 'role' | 'active' | 'features' | 'call_exam_types'> & { phone: string }
const newAccount = (): AccountDraft => ({ name: '', email: '', phone: '', role: 'radiologist', active: true, features: Object.fromEntries(Object.keys(FEATURES).map(k => [k, true])) as Account['features'], call_exam_types: Object.keys(EXAMS) })
const createId = () => crypto.randomUUID?.() || `setting-${Date.now()}-${Array.from(crypto.getRandomValues(new Uint32Array(2))).join('-')}`
const initials = (name: string) => name.trim().split(/\s+/).slice(0, 2).map(w => w[0]).join('').toUpperCase()
const formatDate = (value?: string | null) => value ? new Date(value).toLocaleString('fr-FR', { dateStyle: 'short', timeStyle: 'short' }) : '—'
const sizeLabel = (size: number) => `${(size / 1024 / 1024).toLocaleString('fr-FR', { maximumFractionDigits: 2 })} Mo`
function Toggle({ label, checked, onChange, disabled = false }: { label: string; checked: boolean; onChange: (value: boolean) => void; disabled?: boolean }) {
  return <button type="button" role="switch" aria-label={label} aria-checked={checked} disabled={disabled} onClick={() => onChange(!checked)} className={`toggle ${checked ? 'on' : ''}`} />
}
function Field({ label, value, onChange, type = 'text', options, required = false, children }: { label: string; value: string | number; onChange: (value: string) => void; type?: string; options?: Array<string | [string, string]>; required?: boolean; children?: ReactNode }) {
  const id = `setting-${label.replace(/[^\p{L}\p{N}]/gu, '-')}`
  return <div><label htmlFor={id} className="block text-sm font-medium text-slate-700 mb-1.5">{label}{required && ' *'}</label>{options ? <select id={id} className={inputClass} value={value} onChange={e => onChange(e.target.value)}>{options.map(option => <option key={Array.isArray(option) ? option[0] : option} value={Array.isArray(option) ? option[0] : option}>{Array.isArray(option) ? option[1] : option}</option>)}</select>
    : type === 'textarea' ? <textarea id={id} rows={5} className={inputClass} value={value} onChange={e => onChange(e.target.value)} />
    : <input id={id} className={inputClass} type={type} required={required} min={type === 'number' ? 0 : undefined} step={type === 'number' ? 'any' : undefined} value={value} onChange={e => onChange(type === 'tel' ? formatPhoneNumber(e.target.value) : e.target.value)} />}{children}</div>
}
function Panel({ title, subtitle, action, children }: { title: string; subtitle?: string; action?: ReactNode; children: ReactNode }) {
  return <section className="bg-white rounded-2xl border border-slate-200 shadow-sm"><div className="settings-card-header p-5 border-b border-slate-100 flex items-center justify-between"><div><h2 className="font-bold text-lg text-slate-800">{title}</h2>{subtitle && <p className="text-xs text-slate-500 mt-0.5">{subtitle}</p>}</div>{action}</div>{children}</section>
}
function SettingsTable({ columns, children }: { columns: string[]; children: ReactNode }) {
  return <div className="overflow-x-auto"><table className="settings-table w-full text-sm"><thead><tr className="bg-slate-50 text-xs uppercase text-slate-500 tracking-wide border-b border-slate-100">{columns.map(c => <th key={c} className="text-left font-semibold py-3 px-5">{c}</th>)}</tr></thead><tbody className="divide-y divide-slate-100">{children}</tbody></table></div>
}
function Status({ active }: { active: boolean }) { return <span className={`inline-flex items-center gap-1 text-xs font-medium px-2.5 py-1 rounded-full ${active ? 'bg-emerald-50 text-emerald-700' : 'bg-slate-100 text-slate-600'}`}><span className={`w-1.5 h-1.5 rounded-full ${active ? 'bg-emerald-500' : 'bg-slate-400'}`} />{active ? 'Actif' : 'Inactif'}</span> }

export function CimaSettingsPage() {
  const account = useAccountStore(s => s.user), token = useAccountStore(s => s.token)
  const [params, setParams] = useSearchParams()
  const section = sections.some(s => s[0] === params.get('section')) ? params.get('section')! : 'clinic'
  const chooseSection = (id: string) => { const p = new URLSearchParams(params); p.set('section', id); setParams(p) }
  const [search, setSearch] = useState(''), [config, setConfig] = useState<ClinicConfig | null>(null), [saved, setSaved] = useState<ClinicConfig | null>(null)
  const [accounts, setAccounts] = useState<Account[]>([]), [roles, setRoles] = useState<AccountRole[]>([]), [meta, setMeta] = useState<Record<number, string | null>>({})
  const [system, setSystem] = useState<ClinicSystem | null>(null), [logs, setLogs] = useState<AuditLog[]>([]), [logDate, setLogDate] = useState('')
  const [busy, setBusy] = useState(false), [loading, setLoading] = useState(false), [error, setError] = useState('')
  const [userModal, setUserModal] = useState(false), [userId, setUserId] = useState<number | undefined>(), [userDraft, setUserDraft] = useState<AccountDraft>(newAccount)
  const [roleModal, setRoleModal] = useState(false), [roleName, setRoleName] = useState(''), [activeRole, setActiveRole] = useState('radiologist')
  const [echoDoctor, setEchoDoctor] = useState('')
  const [entity, setEntity] = useState<{ kind: 'tax' | 'currency' | 'model'; id?: string } | null>(null)
  const [entityDraft, setEntityDraft] = useState({ name: '', code: '', rate: '0', type: 'Compte rendu', active: true, default: false, body: '' })
  const [alertsOpen, setAlertsOpen] = useState(false), [alerts, setAlerts] = useState<Array<{ id: string; title: string; description: string }>>([])
  const [preview, setPreview] = useState<ClinicConfig['documents']['models'][number] | null>(null)
  const [confirm, setConfirm] = useState<'restore' | 'reset' | null>(null), [confirmText, setConfirmText] = useState(''), [restoreName, setRestoreName] = useState(''), [restoreData, setRestoreData] = useState('')
  const logoInput = useRef<HTMLInputElement>(null), restoreInput = useRef<HTMLInputElement>(null)
  const load = async () => {
    if (account?.role !== 'admin') return
    setLoading(true)
    try {
      const [c, a, d, p, info, m] = await Promise.all([getClinicConfig(), getAccounts(), getAccountDirectory(), getCallPolicy(), getClinicSystem(), fetchApi<Array<{ id: number; last_login: string | null }>>('/clinic-config/users-meta')])
      if (useAccountStore.getState().token !== token || useAccountStore.getState().user?.role !== 'admin') return
      setConfig(c); setSaved(structuredClone(c)); setAccounts(a); setRoles(d.roles); setEchoDoctor(p.echo_doctor_id ? String(p.echo_doctor_id) : ''); setSystem(info); setMeta(Object.fromEntries(m.map(item => [item.id, item.last_login]))); setError('')
    } catch (err) { setError((err as Error).message) } finally { setLoading(false) }
  }
  useEffect(() => { setConfig(null); setSaved(null); if (account?.role === 'admin') void load() }, [token, account?.role])
  useEffect(() => { if (section === 'journal' && account?.role === 'admin') getClinicJournal(logDate).then(setLogs).catch(err => setError(err.message)) }, [section, logDate, token])
  const update = <K extends keyof ClinicConfig>(key: K, value: ClinicConfig[K]) => setConfig(c => c ? { ...c, [key]: value } : c)
  const persist = async <K extends keyof ClinicConfig>(key: K, value: ClinicConfig[K]) => {
    const result = await saveClinicSection(key, value)
    setConfig(c => c ? { ...c, [key]: result } : c); setSaved(c => c ? { ...c, [key]: structuredClone(result) } : c)
    window.dispatchEvent(new Event('clinic-settings-updated')); toast.success('Paramètres enregistrés')
  }
  const run = async (action: () => Promise<void>) => { if (busy) return; setBusy(true); try { await action(); setError('') } catch (err) { setError((err as Error).message); toast.error((err as Error).message) } finally { setBusy(false) } }
  const saveButton = (key: keyof ClinicConfig) => <button type="button" disabled={busy} className={primary} onClick={() => void run(() => persist(key, config![key]))}>Enregistrer</button>
  const openUser = (user?: Account) => { setUserId(user?.id); setUserDraft(user ? { ...user, phone: user.phone || '' } : newAccount()); setUserModal(true) }
  const permission = (role: string, module: string, url: string): Permission => module === 'settings' && role !== 'admin' ? { view: false, create: false, edit: false, delete: false } : config?.permissions[role]?.[module] || { view: role === 'admin' || (module === 'ready_files' ? true : !DEFAULT_ROLE_PERMISSIONS[role] || DEFAULT_ROLE_PERMISSIONS[role].includes(url)), create: role === 'admin' || module !== 'dashboard', edit: role === 'admin' || module !== 'dashboard', delete: role === 'admin' }
  const openEntity = (kind: 'tax' | 'currency' | 'model', id?: string) => {
    const item = kind === 'tax' ? config!.taxes.items.find(t => t.id === id) : kind === 'currency' ? config!.currencies.find(c => c.code === id) : config!.documents.models.find(m => m.id === id)
    setEntityDraft({ name: item?.name || '', code: kind === 'currency' && item && 'code' in item ? item.code : '', rate: item && 'rate' in item ? String(item.rate) : '0', type: item && 'type' in item ? item.type : kind === 'tax' ? 'Vente & Achat' : 'Compte rendu', active: item && 'active' in item ? item.active : true, default: item && 'default' in item ? item.default : false, body: item && 'body' in item ? item.body : '' }); setEntity({ kind, id })
  }
  const rowButton = (label: string, icon: ReactNode, onClick: () => void, danger = false) => <button type="button" disabled={busy} title={label} aria-label={label} onClick={onClick} className={`p-1.5 text-slate-400 ${danger ? 'hover:text-red-600 hover:bg-red-50' : 'hover:text-indigo-600 hover:bg-indigo-50'} rounded-lg transition`}>{icon}</button>
  const notificationIcon = (id: string) => ['waiting', 'unpaid'].includes(id) ? AlertTriangle : id === 'backup' ? Database : id === 'payment' ? Check : Bell
  return <BaseLayout><div className="cima-settings" data-testid="cima-settings">
    <link rel="stylesheet" href={`${import.meta.env.BASE_URL}cima/inter.css`} />
    <div className="px-4 lg:px-8 pt-6 pb-4"><h1 className="text-2xl font-bold text-slate-800">Paramètres</h1><p className="text-sm text-slate-500 mt-1">Configurez votre logiciel selon les besoins de votre clinique.</p></div>
    <div className="px-4 lg:px-8 pb-8 flex flex-col lg:flex-row gap-6">
      <aside className="lg:w-64 shrink-0"><div className="bg-white rounded-2xl border border-slate-200 shadow-sm overflow-hidden sticky top-4">
        <div className="p-3 border-b border-slate-100"><div className="flex items-center gap-2 bg-slate-50 border border-slate-200 rounded-lg px-3 py-2"><Search className="w-4 h-4 text-slate-400 shrink-0" /><input aria-label="Rechercher un paramètre" value={search} onChange={e => setSearch(e.target.value)} placeholder="Rechercher..." className="bg-transparent text-sm outline-none w-full placeholder:text-slate-400" /></div></div>
        <nav className="p-2" role="tablist" aria-label="Rubriques des paramètres">{sections.filter(s => s[1].normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase().includes(search.normalize('NFD').replace(/[\u0300-\u036f]/g, '').toLowerCase())).map(([id, name, Icon]) => <button type="button" role="tab" aria-selected={section === id} aria-controls={`settings-panel-${id}`} id={`settings-tab-${id}`} key={id} onClick={() => chooseSection(id)} className={`settings-nav-item ${section === id ? 'active' : ''} w-full flex items-center gap-3 px-3 py-2.5 rounded-lg text-sm text-slate-700 text-left mb-0.5`}><Icon className="w-4 h-4 shrink-0" /><span>{name}</span></button>)}</nav>
      </div></aside>
      <div className="flex-1 min-w-0 space-y-6" role="tabpanel" id={`settings-panel-${section}`} aria-labelledby={`settings-tab-${section}`}>
        {section === 'printers' && <PrinterSettingsPanel />}
        {section !== 'printers' && account?.role !== 'admin' && <Panel title="Paramètres de la clinique" subtitle="Administration"><p className="p-5 text-sm text-slate-600">Choisissez un compte administrateur depuis « Changer de compte » pour gérer la clinique et les utilisateurs.</p></Panel>}
        {section !== 'printers' && loading && <p role="status">Chargement des paramètres…</p>}
        {section !== 'printers' && error && <div role="alert" className="bg-red-50 border border-red-200 text-red-700 rounded-xl p-4 text-sm">{error}<button type="button" className="ml-3 underline" onClick={() => void load()}>Réessayer</button></div>}
        {config && section === 'clinic' && <Panel title="Informations de la clinique" subtitle="Ces informations apparaissent sur vos documents" action={saveButton('clinic')}>
          <div className="p-5 grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="md:col-span-2 flex items-center gap-4 p-4 bg-slate-50 rounded-xl"><div className="w-20 h-20 rounded-2xl bg-gradient-to-br from-indigo-500 to-purple-600 flex items-center justify-center text-white text-2xl font-bold shadow-lg shrink-0 overflow-hidden">{config.clinic.logo ? <img src={config.clinic.logo} alt="Logo de la clinique" className="w-full h-full object-contain bg-white" /> : initials(config.clinic.name).slice(0, 2) || 'CL'}</div><div className="flex-1"><p className="text-sm font-medium text-slate-800 mb-1">Logo de la clinique</p><p className="text-xs text-slate-500 mb-3">PNG, JPG ou WebP — 500×500px recommandé</p><div className="flex flex-wrap items-center gap-2"><button type="button" onClick={() => logoInput.current?.click()} className="text-xs bg-indigo-600 hover:bg-indigo-700 text-white font-medium px-3 py-1.5 rounded-lg transition">Changer le logo</button><button type="button" onClick={() => update('clinic', { ...config.clinic, logo: '' })} className="text-xs text-slate-500 hover:text-slate-700 font-medium px-3 py-1.5 rounded-lg hover:bg-white transition">Supprimer</button></div><input ref={logoInput} type="file" accept="image/png,image/jpeg,image/webp" aria-label="Fichier du logo" className="hidden" onChange={async e => { const file = e.target.files?.[0]; if (!file) return; if (file.size > 2_000_000) { toast.error('Le logo doit faire moins de 2 Mo.'); return } const reader = new FileReader(); reader.onload = () => update('clinic', { ...config.clinic, logo: String(reader.result) }); reader.readAsDataURL(file); e.target.value = '' }} /></div></div>
            <div className="md:col-span-2"><Field label="Nom de la clinique" value={config.clinic.name} required onChange={v => update('clinic', { ...config.clinic, name: v })} /></div>
            {([['legal_form', 'Forme juridique', ['SARL', 'EURL', 'SPA', 'SNC', 'Cabinet individuel', 'Association']], ['capital', 'Capital social'], ['nif', 'NIF'], ['nis', 'NIS'], ['rc', 'RC (Registre de Commerce)'], ['tax_number', 'N° Article d’imposition'], ['address', 'Adresse de la clinique'], ['postal_code', 'Code postal'], ['city', 'Wilaya / Ville'], ['phone', 'Téléphone'], ['email', 'Email'], ['website', 'Site web'], ['bank', 'Banque'], ['rib', 'RIB']] as Array<[string, string, string[]?]>).map(([key, label, options]) => <div key={key} className={key === 'address' ? 'md:col-span-2' : ''}><Field label={label} value={config.clinic[key]} options={options} type={key === 'phone' ? 'tel' : key === 'email' ? 'email' : key === 'website' ? 'url' : key === 'capital' ? 'number' : 'text'} onChange={v => update('clinic', { ...config.clinic, [key]: v })} /></div>)}
            <Field label="Devise par défaut" value={config.clinic.currency} options={config.currencies.filter(c => c.active).map(c => [c.code, `${c.code} — ${c.name}`])} onChange={v => update('clinic', { ...config.clinic, currency: v })} />
            <Field label="Langue par défaut" value={config.clinic.language} options={[["fr", 'Français'], ['ar', 'العربية'], ['en', 'English']]} onChange={v => update('clinic', { ...config.clinic, language: v })} />
            <Field label="Fuseau horaire" value={config.clinic.timezone} options={[["Africa/Algiers", '(GMT+1) Alger'], ['Africa/Casablanca', 'Casablanca'], ['Europe/Paris', 'Paris']]} onChange={v => update('clinic', { ...config.clinic, timezone: v })} />
            <Field label="Format de date" value={config.clinic.date_format} options={[["dd/MM/yyyy", 'JJ/MM/AAAA'], ['MM/dd/yyyy', 'MM/JJ/AAAA'], ['yyyy-MM-dd', 'AAAA-MM-JJ']]} onChange={v => update('clinic', { ...config.clinic, date_format: v })} />
          </div>
        </Panel>}
        {config && section === 'users' && <>
          <Panel title="Utilisateurs" subtitle={`${accounts.length} utilisateurs enregistrés`} action={<button type="button" disabled={busy} className={primary} onClick={() => openUser()}><Plus className="w-4 h-4" />Nouvel utilisateur</button>}>
            <SettingsTable columns={['Utilisateur', 'Rôle', 'Dernière connexion', 'Statut', 'Actions']}>{accounts.map(user => <tr className="row-hover" key={user.id}><td className="py-3 px-5"><div className="flex items-center gap-3"><div className="w-9 h-9 rounded-full bg-indigo-100 text-indigo-700 flex items-center justify-center text-xs font-semibold shrink-0">{initials(user.name)}</div><div><p className="font-medium text-slate-800">{user.name}</p><p className="text-xs text-slate-500">{user.email || '—'}</p></div></div></td><td className="py-3 px-5"><span className={`inline-flex text-xs font-medium px-2.5 py-1 rounded-full ${user.role === 'admin' ? 'bg-red-50 text-red-700' : 'bg-indigo-50 text-indigo-700'}`}>{roles.find(r => r.id === user.role)?.name || user.role}</span></td><td className="py-3 px-5 text-slate-600 text-xs">{formatDate(meta[user.id])}</td><td className="py-3 px-5"><Status active={user.active} /></td><td className="py-3 px-5"><div className="flex items-center justify-end gap-1">{rowButton(`Modifier ${user.name}`, <Pencil className="w-4 h-4" />, () => openUser(user))}{rowButton(`${user.active ? 'Désactiver' : 'Activer'} ${user.name}`, <Ban className="w-4 h-4" />, () => void run(async () => { const result = await saveAccount({ active: !user.active }, user.id); if (user.id === account?.id) useAccountStore.getState().setUser(result); await load(); toast.success('Statut du compte enregistré') }), true)}</div></td></tr>)}</SettingsTable>
          </Panel>
          <Panel title="Appels d’échographie" subtitle="Réservez l’appel à un seul médecin choisi"><div className="p-5 flex flex-wrap items-end gap-3"><div className="flex-1 min-w-48"><Field label="Médecin réservé pour l’échographie" value={echoDoctor} options={[['', 'Tous les comptes autorisés'], ...accounts.filter(a => a.active && a.role === 'radiologist' && a.features.queue_calls && a.call_exam_types.includes('Echo')).map(a => [String(a.id), a.name] as [string, string])]} onChange={setEchoDoctor} /></div><button type="button" className={primary} disabled={busy} onClick={() => void run(async () => { await saveCallPolicy(echoDoctor ? Number(echoDoctor) : null); toast.success('Réservation enregistrée') })}>Enregistrer la réservation</button></div></Panel>
        </>}
        {config && section === 'permissions' && <Panel title="Rôles & Permissions" subtitle="Définissez les droits d’accès par rôle" action={<button type="button" className={primary} onClick={() => { setRoleName(''); setRoleModal(true) }}><Plus className="w-4 h-4" />Nouveau rôle</button>}><div className="p-5">
          <div className="flex flex-wrap items-center gap-2 mb-5">{roles.map(role => <button type="button" key={role.id} onClick={() => setActiveRole(role.id)} className={`px-4 py-2 text-sm font-medium rounded-lg transition ${activeRole === role.id ? 'bg-indigo-600 text-white' : 'bg-slate-100 text-slate-600 hover:bg-slate-200'}`}>{role.name}</button>)}</div>
          <div className="border border-slate-200 rounded-xl overflow-hidden"><SettingsTable columns={['Module / Fonctionnalité', 'Voir', 'Créer', 'Modifier', 'Supprimer']}>{modules.map(([id, name, url]) => { const current = permission(activeRole, id, url); return <tr className="row-hover" key={id}><td className="py-3 px-5"><p className="font-medium text-slate-800">{name}</p><p className="text-xs text-slate-500">{id === 'settings' ? 'Administration de la clinique' : `Gestion : ${name.toLowerCase()}`}</p></td>{(['view', 'create', 'edit', 'delete'] as const).map((action, index) => <td className="py-3 px-3 text-center" key={action}><Toggle label={`${['Voir', 'Créer', 'Modifier', 'Supprimer'][index]} ${name}`} checked={current[action]} disabled={activeRole === 'admin' || id === 'settings' || busy} onChange={checked => update('permissions', { ...config.permissions, [activeRole]: { ...config.permissions[activeRole], [id]: { ...current, [action]: checked } } })} /></td>)}</tr> })}</SettingsTable></div>
          <div className="flex items-center justify-end gap-2 mt-4"><button type="button" className={secondary} onClick={() => update('permissions', structuredClone(saved!.permissions))}>Annuler</button><button type="button" className={primary} disabled={busy} onClick={() => void run(() => persist('permissions', Object.fromEntries(roles.map(role => [role.id, Object.fromEntries(modules.map(([id, , url]) => [id, permission(role.id, id, url)]))]))))}>Enregistrer les permissions</button></div>
        </div></Panel>}
        {config && section === 'taxes' && <Panel title="Taxes & TVA" subtitle="Configurez les taux de TVA applicables" action={<button type="button" className={primary} onClick={() => openEntity('tax')}><Plus className="w-4 h-4" />Ajouter un taux</button>}><div className="p-5">
          <div className="border border-slate-200 rounded-xl overflow-hidden mb-5"><SettingsTable columns={['Nom', 'Taux', 'Type', 'Par défaut', 'Statut', 'Actions']}>{config.taxes.items.map(t => <tr className="row-hover" key={t.id}><td className="py-3 px-5 font-medium text-slate-800">{t.name}</td><td className="py-3 px-5"><span className="inline-flex text-xs font-bold px-2.5 py-1 rounded-full bg-indigo-50 text-indigo-700">{t.rate} %</span></td><td className="py-3 px-5 text-slate-600">{t.type}</td><td className="py-3 px-5">{t.default && <Check className="w-5 h-5 text-emerald-500" />}</td><td className="py-3 px-5"><Status active={t.active} /></td><td className="py-3 px-5"><div className="flex gap-1">{rowButton(`Modifier ${t.name}`, <Pencil className="w-4 h-4" />, () => openEntity('tax', t.id))}{rowButton(`Supprimer ${t.name}`, <Trash2 className="w-4 h-4" />, () => void run(() => persist('taxes', { ...config.taxes, items: config.taxes.items.filter(item => item.id !== t.id) })), true)}</div></td></tr>)}{!config.taxes.items.length && <tr><td colSpan={6} className="p-5 text-slate-500 text-center">Aucun taux configuré. Ajoutez les taux utilisés par la clinique.</td></tr>}</SettingsTable></div>
          <div className="bg-indigo-50 border border-indigo-100 rounded-xl p-4 text-sm text-indigo-900"><p className="font-semibold mb-1">Régime fiscal</p><p className="text-xs mb-3">Les tarifs sont TTC. Le taux actif par défaut est détaillé sur les nouvelles quittances ; les quittances précédentes conservent leur taux.</p><div className="grid grid-cols-1 md:grid-cols-2 gap-3 mt-2">{['Régime réel', 'Régime simplifié', 'Cabinet individuel', 'Exonéré'].map(regime => <label className="flex items-center gap-2 cursor-pointer" key={regime}><input type="radio" name="regime" checked={config.taxes.regime === regime} onChange={() => update('taxes', { ...config.taxes, regime })} />{regime}</label>)}</div><div className="mt-4">{saveButton('taxes')}</div></div>
        </div></Panel>}
        {config && section === 'currencies' && <Panel title="Devises" subtitle="Gérez les devises et taux de change" action={<button type="button" className={primary} onClick={() => openEntity('currency')}><Plus className="w-4 h-4" />Ajouter une devise</button>}><div className="p-5"><div className="bg-amber-50 border border-amber-100 rounded-xl p-4 mb-5 flex items-start gap-3"><AlertTriangle className="w-5 h-5 text-amber-600 shrink-0 mt-0.5" /><p className="text-sm text-amber-900">La devise de référence est <strong>DZD — Dinar algérien</strong>. Les conversions utilisent les taux que vous renseignez ci-dessous.</p></div><div className="border border-slate-200 rounded-xl overflow-hidden"><SettingsTable columns={['Devise', 'Code', 'Taux (1 unité = X DZD)', 'Dernière MAJ', 'Statut', 'Actions']}>{config.currencies.map(c => <tr className={`row-hover ${c.code === 'DZD' ? 'bg-indigo-50/30' : ''}`} key={c.code}><td className="py-3 px-5 font-medium text-slate-800">{c.name}</td><td className="py-3 px-5 font-mono text-xs font-semibold text-slate-800">{c.code}</td><td className="py-3 px-5 font-semibold text-slate-800">{c.rate.toLocaleString('fr-FR')}{c.code === 'DZD' && <span className="ml-1 text-xs text-indigo-600 font-medium">(référence)</span>}</td><td className="py-3 px-5 text-xs text-slate-500">{formatDate(c.updated_at)}</td><td className="py-3 px-5"><Status active={c.active} /></td><td className="py-3 px-5">{c.code !== 'DZD' ? rowButton(`Actualiser le taux ${c.code}`, <RefreshCw className="w-4 h-4" />, () => openEntity('currency', c.code)) : '—'}</td></tr>)}</SettingsTable></div></div></Panel>}
        {config && section === 'payments' && <Panel title="Modes de paiement" subtitle="Activez les moyens de paiement acceptés" action={saveButton('payments')}><div className="p-5 space-y-3">{config.payments.map((p, i) => <div className="flex items-center justify-between gap-4 p-4 border border-slate-200 rounded-xl hover:bg-slate-50 transition" key={p.id}><div className="flex items-center gap-4"><div className={`w-11 h-11 rounded-xl flex items-center justify-center shrink-0 ${i % 2 ? 'bg-indigo-50 text-indigo-600' : 'bg-emerald-50 text-emerald-600'}`}><CreditCard className="w-5 h-5" /></div><div><p className="font-medium text-slate-800">{p.name}</p><p className="text-xs text-slate-500">{p.name === 'Crédit patient' ? 'Paiement différé' : `Paiement par ${p.name.toLowerCase()}`}</p></div></div><Toggle label={p.name} checked={p.active} onChange={active => update('payments', config.payments.map(item => item.id === p.id ? { ...item, active } : item))} /></div>)}</div></Panel>}
        {config && section === 'documents' && <>
          <Panel title="Modèles de documents" subtitle="Personnalisez l’apparence de vos documents" action={<button type="button" className={primary} onClick={() => openEntity('model')}><Plus className="w-4 h-4" />Nouveau modèle</button>}><div className="p-5 grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-4">{config.documents.models.map(m => <div className="border border-slate-200 rounded-xl overflow-hidden hover:shadow-lg transition group" key={m.id}><div className="aspect-[3/4] bg-gradient-to-br from-slate-100 to-slate-200 relative flex items-center justify-center"><div className="absolute inset-4 bg-white rounded shadow-sm p-3 text-[8px]"><div className="flex justify-between mb-2"><div className="w-8 h-3 rounded" style={{ background: config.documents.color }} /><div className="w-12 h-2 bg-slate-200 rounded" /></div><div className="space-y-1"><div className="h-1.5 bg-slate-200 rounded w-3/4" /><div className="h-1.5 bg-slate-200 rounded w-1/2" /></div><div className="mt-3 space-y-1">{[1, 2, 3, 4, 5].map(i => <div key={i} className="h-1 bg-slate-100 rounded" />)}</div><p className="mt-3 text-slate-500 whitespace-pre-wrap line-clamp-6">{m.body}</p><div className="mt-3 flex justify-end"><div className="w-12 h-2 rounded" style={{ background: config.documents.color }} /></div></div><div className="absolute inset-0 bg-indigo-600/80 opacity-0 group-hover:opacity-100 group-focus-within:opacity-100 flex items-center justify-center gap-2 transition"><button type="button" className="bg-white text-indigo-600 text-xs font-medium px-3 py-1.5 rounded-lg" onClick={() => setPreview(m)}>Aperçu</button><button type="button" className="bg-white text-indigo-600 text-xs font-medium px-3 py-1.5 rounded-lg" onClick={() => openEntity('model', m.id)}>Modifier</button></div></div><div className="p-3 border-t border-slate-100"><p className="text-sm font-medium text-slate-800">{m.name}</p><div className="flex items-center justify-between mt-1"><p className="text-xs text-slate-500">{m.type}</p>{m.default && <span className="text-[10px] font-medium bg-emerald-50 text-emerald-700 px-2 py-0.5 rounded-full">Par défaut</span>}</div></div></div>)}</div></Panel>
          <Panel title="Personnalisation des documents" action={saveButton('documents')}><div className="p-5 space-y-4"><Field label="Conditions générales de la clinique" type="textarea" value={config.documents.conditions} onChange={conditions => update('documents', { ...config.documents, conditions })} /><Field label="Pied de page des documents" value={config.documents.footer} onChange={footer => update('documents', { ...config.documents, footer })} /><div className="grid grid-cols-1 md:grid-cols-2 gap-4"><div><label htmlFor="document-color" className="block text-sm font-medium text-slate-700 mb-1.5">Couleur principale</label><div className="flex items-center gap-3"><input id="document-color" type="color" value={config.documents.color} onChange={e => update('documents', { ...config.documents, color: e.target.value })} className="w-12 h-10 rounded-lg border border-slate-200 cursor-pointer" /><input aria-label="Code couleur des documents" value={config.documents.color} className={`${inputClass} font-mono`} onChange={e => update('documents', { ...config.documents, color: e.target.value })} /></div></div><Field label="Police des documents" value={config.documents.font} options={['Inter', 'Arial', 'Roboto', 'Times New Roman']} onChange={font => update('documents', { ...config.documents, font })} /></div></div></Panel>
        </>}
        {config && section === 'notifications' && <>
          <Panel title="Notifications & Alertes" subtitle="Configurez les alertes automatiques" action={saveButton('notifications')}><div className="p-5 space-y-3">{config.notifications.items.map(n => { const Icon = notificationIcon(n.id); return <div className="flex items-center justify-between gap-4 p-4 border border-slate-200 rounded-xl hover:bg-slate-50 transition" key={n.id}><div className="flex items-start gap-4 flex-1 min-w-0"><div className="w-11 h-11 rounded-xl flex items-center justify-center shrink-0 bg-indigo-50 text-indigo-600"><Icon className="w-5 h-5" /></div><div className="flex-1 min-w-0"><p className="font-medium text-slate-800">{n.name}</p><p className="text-xs text-slate-500 mt-0.5">{n.description}</p>{n.active && n.threshold != null && <div className="mt-2 flex items-center gap-2 text-xs"><label htmlFor={`threshold-${n.id}`} className="text-slate-500">Seuil :</label><input id={`threshold-${n.id}`} aria-label={`Seuil ${n.name}`} type="number" min={1} max={1440} value={n.threshold} onChange={e => update('notifications', { ...config.notifications, items: config.notifications.items.map(item => item.id === n.id ? { ...item, threshold: Number(e.target.value) } : item) })} className="w-20 bg-white border border-slate-200 rounded px-2 py-1 text-xs outline-none" /><span className="text-slate-500">{n.unit}</span></div>}</div></div><Toggle label={n.name} checked={n.active} onChange={active => update('notifications', { ...config.notifications, items: config.notifications.items.map(item => item.id === n.id ? { ...item, active } : item) })} /></div> })}</div></Panel>
          <button type="button" className={secondary} disabled={busy} onClick={() => void run(async () => { const result = await fetchApi<{ items: typeof alerts }>('/notifications'); setAlerts(result.items); setAlertsOpen(true) })}><Bell className="w-4 h-4" />Consulter les alertes actuelles</button>
          <Panel title="Canaux de notification" subtitle="Comment souhaitez-vous être notifié ?"><div className="p-5 space-y-3">{([['email', 'Email', Mail, 'Aucun service email configuré'], ['sms', 'SMS', MessageSquare, 'Aucun service SMS configuré'], ['application', 'Notifications push', Bell, 'Alertes dans l’application']] as const).map(([id, name, Icon, description]) => <div className="flex items-center justify-between gap-4 p-4 border border-slate-200 rounded-xl" key={id}><div className="flex items-center gap-3"><div className="w-10 h-10 rounded-lg bg-blue-50 text-blue-600 flex items-center justify-center shrink-0"><Icon className="w-5 h-5" /></div><div><p className="font-medium text-slate-800">{name}</p><p className="text-xs text-slate-500">{description}</p></div></div><Toggle label={name} disabled={id !== 'application'} checked={config.notifications.channels[id]} onChange={v => update('notifications', { ...config.notifications, channels: { ...config.notifications.channels, [id]: v } })} /></div>)}</div></Panel>
        </>}
        {config && section === 'security' && <>
          <Panel title="Sauvegarde des données" subtitle="Protégez vos données avec des sauvegardes régulières"><div className="p-5"><div className="grid grid-cols-1 md:grid-cols-3 gap-4 mb-5">{[['Dernière sauvegarde', formatDate(system?.backups[0]?.created_at), system?.backups.length ? 'Sauvegarde locale' : 'Aucune sauvegarde'], ['Taille de la base', sizeLabel(system?.database_size || 0), 'Base SQLite de la clinique'], ['Sauvegardes conservées', String(system?.backups.length || 0), `Rotation : ${config.security.retention} maximum`]].map(([title, value, description]) => <div className="border border-slate-200 rounded-xl p-4" key={title}><p className="text-xs text-slate-500 uppercase tracking-wide">{title}</p><p className="text-lg font-bold text-slate-800 mt-1">{value}</p><p className="text-xs text-slate-500">{description}</p></div>)}</div><div className="space-y-3 mb-5"><div className="flex items-center justify-between p-4 border border-slate-200 rounded-xl"><div><p className="font-medium text-slate-800">Sauvegarde automatique</p><p className="text-xs text-slate-500">Effectuée chaque jour à {config.security.backup_time}, lorsque le serveur est ouvert</p></div><Toggle label="Sauvegarde automatique" checked={config.security.automatic_backup} onChange={automatic_backup => update('security', { ...config.security, automatic_backup })} /></div><div className="flex items-center justify-between p-4 border border-slate-200 rounded-xl"><div><p className="font-medium text-slate-800">Sauvegarde cloud</p><p className="text-xs text-slate-500">Aucun stockage distant configuré</p></div><Toggle label="Sauvegarde cloud" disabled checked={false} onChange={() => {}} /></div><div className="flex items-center justify-between p-4 border border-slate-200 rounded-xl"><div><p className="font-medium text-slate-800">Chiffrement des sauvegardes</p><p className="text-xs text-slate-500">AES-256 — restauration sur ce serveur</p></div><Toggle label="Chiffrement des sauvegardes" checked={config.security.encrypted_backup} onChange={encrypted_backup => update('security', { ...config.security, encrypted_backup })} /></div><div className="grid md:grid-cols-2 gap-4"><Field label="Heure de sauvegarde" type="time" value={config.security.backup_time} onChange={backup_time => update('security', { ...config.security, backup_time })} /><Field label="Nombre de sauvegardes à conserver" type="number" value={config.security.retention} onChange={v => update('security', { ...config.security, retention: Number(v) })} /></div>{saveButton('security')}</div><div className="flex flex-wrap items-center gap-3"><button type="button" disabled={busy} className={primary} onClick={() => void run(async () => { await createClinicBackup(); setSystem(await getClinicSystem()); toast.success('Sauvegarde créée') })}><Download className="w-4 h-4" />Sauvegarder maintenant</button><button type="button" disabled={busy} className={secondary} onClick={() => { setConfirmText(''); setRestoreName(system?.backups[0]?.name || ''); setRestoreData(''); setConfirm('restore') }}><Upload className="w-4 h-4" />Restaurer une sauvegarde</button><button type="button" disabled={busy || !system?.backups.length} className={secondary} onClick={() => void run(() => downloadClinicBackup(system!.backups[0].name))}><FileText className="w-4 h-4" />Télécharger la dernière sauvegarde</button></div></div></Panel>
          <Panel title="Sécurité" subtitle="Gérez les accès aux comptes de la clinique"><div className="p-5 space-y-3">{[['Authentification à deux facteurs (2FA)', 'Indisponible dans le mode de choix de compte sans mot de passe'], ['Politique de mot de passe', 'Le mode actuel ne demande aucun mot de passe']].map(([title, description]) => <div className="flex items-center justify-between gap-3 p-4 border border-slate-200 rounded-xl" key={title}><div className="flex items-center gap-3"><ShieldCheck className="w-5 h-5 text-red-600 shrink-0" /><div><p className="font-medium text-slate-800">{title}</p><p className="text-xs text-slate-500">{description}</p></div></div><button type="button" disabled title={description} className="text-sm font-medium text-indigo-600">{title.startsWith('Authentification') ? 'Activer' : 'Modifier'}</button></div>)}<div className="p-4 border border-slate-200 rounded-xl"><Field label="Déconnexion automatique (minutes)" type="number" value={config.security.session_timeout} onChange={v => update('security', { ...config.security, session_timeout: Number(v) })} /><p className="text-xs text-slate-500 mt-2">0 : rester connecté. Une session expirée demande de choisir à nouveau un compte.</p></div><div className="flex items-center justify-between p-4 border border-slate-200 rounded-xl"><div><p className="font-medium text-slate-800">Journal d’activité</p><p className="text-xs text-slate-500">Consulter qui a fait quoi et quand</p></div><button type="button" className="text-sm font-medium text-indigo-600" onClick={() => chooseSection('journal')}>Consulter</button></div>{saveButton('security')}</div></Panel>
          <Panel title="Maintenance & Système" subtitle="Informations techniques et maintenance"><div className="p-5"><dl className="grid grid-cols-1 md:grid-cols-2 gap-4 mb-5">{[['Version', system?.version || '—'], ['Mode d’utilisation', system?.mode || '—'], ['Utilisateurs connectés', String(system?.connected_users || 0)], ['Base de données', 'SQLite — stockage local']].map(([label, value]) => <div className="bg-slate-50 rounded-xl p-4" key={label}><dt className="text-xs text-slate-500 uppercase">{label}</dt><dd className="text-sm font-semibold text-slate-800 mt-1">{value}</dd></div>)}</dl><div className="flex flex-wrap items-center gap-3"><button type="button" className={secondary} disabled={busy} onClick={() => void run(async () => { const info = await getClinicSystem(); setSystem(info); toast.info(`${info.version}. Aucun service de mise à jour distant configuré.`) })}><RefreshCw className="w-4 h-4" />Vérifier les mises à jour</button><button type="button" className={secondary} disabled={busy} onClick={() => void run(async () => { if ('caches' in window) for (const key of await caches.keys()) if (key.startsWith('radiomed-')) await caches.delete(key); await load(); toast.success('Cache de l’application actualisé') })}><Settings className="w-4 h-4" />Vider le cache</button><button type="button" className="bg-white border border-red-200 hover:bg-red-50 text-red-600 text-sm font-medium px-4 py-2 rounded-lg transition inline-flex items-center gap-2" disabled={busy} onClick={() => { setConfirmText(''); setConfirm('reset') }}><Trash2 className="w-4 h-4" />Réinitialiser les paramètres</button></div></div></Panel>
        </>}
        {config && section === 'journal' && <Panel title="Journal d’activité" subtitle="Historique des actions effectuées dans l’application" action={<div className="flex items-center gap-2"><input type="date" aria-label="Journal depuis le" value={logDate} onChange={e => setLogDate(e.target.value)} className="bg-slate-50 border border-slate-200 rounded-lg px-3 py-2 text-xs outline-none" /><button type="button" className={secondary} onClick={() => downloadCsv('journal-clinique.csv', [['Date', 'Utilisateur', 'Action', 'Cible'], ...logs.map(l => [l.created_at, l.actor, l.action, l.target])])}><Download className="w-3.5 h-3.5" />Exporter</button></div>}><div className="p-5"><div className="relative pl-8"><div className="absolute left-3 top-2 bottom-2 w-px bg-slate-200" />{logs.map(log => <div className="relative pb-5 last:pb-0" key={log.id}><div className="absolute -left-5 top-0 w-3 h-3 rounded-full ring-4 ring-white bg-indigo-500" /><div className="flex flex-wrap items-start justify-between gap-3"><div><p className="text-sm text-slate-800"><span className="font-medium">{log.actor}</span> {log.action} <span className="font-medium text-indigo-600">{log.target}</span></p><p className="text-xs text-slate-500 mt-1">{formatDate(log.created_at)}</p></div></div></div>)}{!logs.length && <p className="text-sm text-slate-500">Aucune activité pour cette période.</p>}</div></div></Panel>}
        {config && section === 'rooms' && <div className="settings-supplement"><AdminResourceManagement /></div>}
      </div>
    </div>
    <Dialog open={userModal} onOpenChange={open => { if (!busy) setUserModal(open) }}><DialogContent className="cima-settings-dialog sm:max-w-[680px] max-h-[90vh] overflow-y-auto"><DialogHeader><DialogTitle>{userId ? 'Modifier l’utilisateur' : 'Nouvel utilisateur'}</DialogTitle><DialogDescription>Choix du rôle et du compte, sans identifiant ni mot de passe.</DialogDescription></DialogHeader><form className="space-y-5" onSubmit={e => { e.preventDefault(); void run(async () => { const result = await saveAccount(userDraft, userId); if (result.id === account?.id) useAccountStore.getState().setUser(result); setUserModal(false); await load(); toast.success('Utilisateur enregistré') }) }}><div className="grid sm:grid-cols-2 gap-4"><Field label="Nom du compte" value={userDraft.name} required onChange={name => setUserDraft({ ...userDraft, name })} /><Field label="Email (facultatif)" type="email" value={userDraft.email} onChange={email => setUserDraft({ ...userDraft, email })} /><Field label="Téléphone du compte" type="tel" value={userDraft.phone} onChange={phone => setUserDraft({ ...userDraft, phone })} /><Field label="Rôle" value={userDraft.role} options={roles.map(r => [r.id, r.name])} onChange={role => setUserDraft({ ...userDraft, role })} /></div><div className="flex items-center justify-between"><p className="font-medium text-sm">Compte actif</p><Toggle label="Compte actif" checked={userDraft.active} onChange={active => setUserDraft({ ...userDraft, active })} /></div><fieldset><legend className="font-semibold text-sm mb-3">Fonctions activées</legend><div className="grid sm:grid-cols-2 gap-3">{Object.entries(FEATURES).map(([id, label]) => <div className="flex items-center justify-between gap-2 border border-slate-200 rounded-lg p-3" key={id}><span className="text-sm">{label}</span><Toggle label={label} checked={userDraft.features[id as keyof typeof FEATURES]} onChange={v => setUserDraft({ ...userDraft, features: { ...userDraft.features, [id]: v } })} /></div>)}</div></fieldset><fieldset disabled={!userDraft.features.queue_calls}><legend className="font-semibold text-sm mb-3">Appel autorisé par type d’examen</legend><div className="grid sm:grid-cols-3 gap-3">{Object.entries(EXAMS).map(([id, label]) => <div className="flex items-center justify-between gap-2" key={id}><span className="text-sm">{label}</span><Toggle label={`Appel ${label}`} disabled={!userDraft.features.queue_calls} checked={userDraft.call_exam_types.includes(id)} onChange={checked => setUserDraft({ ...userDraft, call_exam_types: checked ? [...userDraft.call_exam_types, id] : userDraft.call_exam_types.filter(k => k !== id) })} /></div>)}</div></fieldset><div className="flex justify-end gap-2"><button type="button" disabled={busy} className={secondary} onClick={() => setUserModal(false)}>Annuler</button><button type="submit" className={primary} disabled={busy}>{busy ? 'Enregistrement…' : userId ? 'Enregistrer l’utilisateur' : 'Créer l’utilisateur'}</button></div></form></DialogContent></Dialog>
    <Dialog open={roleModal} onOpenChange={open => { if (!busy) setRoleModal(open) }}><DialogContent className="cima-settings-dialog"><DialogHeader><DialogTitle>Nouveau rôle</DialogTitle><DialogDescription>Ce rôle sera proposé dans la création des utilisateurs et le choix du compte.</DialogDescription></DialogHeader><form className="space-y-4" onSubmit={e => { e.preventDefault(); void run(async () => { const role = await createAccountRole(roleName); setRoles(previous => [...previous, role]); setActiveRole(role.id); setRoleModal(false); toast.success('Rôle créé') }) }}><Field label="Nom du rôle" value={roleName} required onChange={setRoleName} /><div className="flex justify-end gap-2"><button type="button" className={secondary} onClick={() => setRoleModal(false)}>Annuler</button><button type="submit" disabled={busy || !roleName.trim()} className={primary}>Créer le rôle</button></div></form></DialogContent></Dialog>
    <Dialog open={!!entity} onOpenChange={open => { if (!open && !busy) setEntity(null) }}><DialogContent className="cima-settings-dialog max-h-[90vh] overflow-y-auto"><DialogHeader><DialogTitle>{entity?.kind === 'tax' ? 'Taux de TVA' : entity?.kind === 'currency' ? 'Devise et taux de change' : 'Modèle de document'}</DialogTitle><DialogDescription>{entity?.kind === 'model' ? 'Personnalisez le contenu et le modèle par défaut.' : 'Renseignez les valeurs utilisées par la clinique.'}</DialogDescription></DialogHeader><form className="space-y-4" onSubmit={e => { e.preventDefault(); if (!entity || !config) return; void run(async () => {
      if (entity.kind === 'tax') { const tax = { id: entity.id || createId(), name: entityDraft.name.trim(), rate: Number(entityDraft.rate), type: entityDraft.type, active: entityDraft.active, default: entityDraft.default }; await persist('taxes', { ...config.taxes, items: [...config.taxes.items.filter(t => t.id !== tax.id).map(t => tax.default ? { ...t, default: false } : t), tax] }) }
      if (entity.kind === 'currency') { const currency = { code: entityDraft.code.toUpperCase().trim(), name: entityDraft.name.trim(), rate: Number(entityDraft.rate), active: entityDraft.active, updated_at: new Date().toISOString() }; if (!entity.id && config.currencies.some(c => c.code === currency.code)) throw new Error('Cette devise existe déjà.'); await persist('currencies', [...config.currencies.filter(c => c.code !== entity.id), currency]) }
      if (entity.kind === 'model') { const model = { id: entity.id || createId(), name: entityDraft.name.trim(), type: entityDraft.type, body: entityDraft.body, default: entityDraft.default }; await persist('documents', { ...config.documents, models: [...config.documents.models.filter(m => m.id !== model.id).map(m => model.default && m.type === model.type ? { ...m, default: false } : m), model] }) }
      setEntity(null)
    }) }}><Field label="Nom" value={entityDraft.name} required onChange={name => setEntityDraft({ ...entityDraft, name })} />{entity?.kind === 'currency' && <Field label="Code devise (3 lettres)" value={entityDraft.code} required onChange={code => setEntityDraft({ ...entityDraft, code: code.toUpperCase().slice(0, 3) })} />}{entity?.kind !== 'model' && <Field label={entity?.kind === 'tax' ? 'Taux (%)' : 'Taux (1 unité = X DZD)'} type="number" value={entityDraft.rate} required onChange={rate => setEntityDraft({ ...entityDraft, rate })} />}{entity?.kind !== 'currency' && <Field label="Type" value={entityDraft.type} options={entity?.kind === 'model' ? ['Compte rendu', 'Prescription', 'Quittance', 'Fiche patient', 'Ticket'] : ['Vente & Achat', 'Exonéré', 'Autre']} onChange={type => setEntityDraft({ ...entityDraft, type })} />}{entity?.kind === 'model' && <Field label="Contenu du modèle" type="textarea" value={entityDraft.body} onChange={body => setEntityDraft({ ...entityDraft, body })} />}{entity?.kind !== 'model' && <div className="flex items-center justify-between text-sm"><span>Actif</span><Toggle label="Actif" checked={entityDraft.active} onChange={active => setEntityDraft({ ...entityDraft, active })} /></div>}{entity?.kind !== 'currency' && <div className="flex items-center justify-between text-sm"><span>Par défaut</span><Toggle label="Par défaut" checked={entityDraft.default} onChange={v => setEntityDraft({ ...entityDraft, default: v })} /></div>}<div className="flex justify-end gap-2"><button type="button" disabled={busy} className={secondary} onClick={() => setEntity(null)}>Annuler</button><button type="submit" disabled={busy} className={primary}>Enregistrer</button></div></form></DialogContent></Dialog>
    <Dialog open={!!preview} onOpenChange={open => { if (!open) setPreview(null) }}><DialogContent className="cima-settings-dialog sm:max-w-[650px] max-h-[90vh] overflow-y-auto"><DialogHeader><DialogTitle>Aperçu — {preview?.name}</DialogTitle><DialogDescription>Aperçu du modèle avec les informations de la clinique.</DialogDescription></DialogHeader>{config && <div className="border border-slate-200 p-6 min-h-96" data-testid="document-template-preview" style={{ fontFamily: config.documents.font, borderTop: `4px solid ${config.documents.color}` }}>{config.clinic.logo && <img src={config.clinic.logo} alt="Logo de la clinique" className="w-16 h-16 object-contain mb-3" />}<h2 className="font-bold" style={{ color: config.documents.color }}>{config.clinic.name}</h2><p className="text-xs text-slate-500">{config.clinic.address} · {formatPhoneNumber(config.clinic.phone)}</p><h3 className="my-5 font-semibold">{preview?.type}</h3><div className="whitespace-pre-wrap text-sm">{preview?.body || 'Le contenu sera complété dans le document du patient.'}</div><p className="mt-8 text-xs text-slate-500 whitespace-pre-wrap">{config.documents.conditions}</p><footer className="mt-5 pt-3 border-t border-slate-200 text-xs text-slate-500">{config.documents.footer}</footer></div>}</DialogContent></Dialog>
    <Dialog open={alertsOpen} onOpenChange={setAlertsOpen}><DialogContent className="cima-settings-dialog"><DialogHeader><DialogTitle>Alertes de la clinique</DialogTitle><DialogDescription>Alertes calculées selon les réglages enregistrés.</DialogDescription></DialogHeader><div className="space-y-3">{alerts.map(alert => <div key={alert.id} className="border border-slate-200 rounded-xl p-4"><p className="font-semibold text-sm">{alert.title}</p><p className="text-xs text-slate-500 mt-1">{alert.description}</p></div>)}{!alerts.length && <p className="text-sm text-slate-500">Aucune alerte actuellement.</p>}</div></DialogContent></Dialog>
    <Dialog open={!!confirm} onOpenChange={open => { if (!open && !busy) setConfirm(null) }}><DialogContent className="cima-settings-dialog"><DialogHeader><DialogTitle>{confirm === 'restore' ? 'Restaurer une sauvegarde' : 'Réinitialiser les paramètres'}</DialogTitle><DialogDescription>{confirm === 'restore' ? 'La restauration remplacera les dossiers et paramètres par ceux de la sauvegarde. Une copie de sécurité est créée avant la restauration. Les comptes devront se reconnecter.' : 'Une copie de sécurité sera créée. Les réglages reviennent à leurs valeurs initiales. Les dossiers patients, comptes et salles sont conservés.'}</DialogDescription></DialogHeader><form className="space-y-4" onSubmit={e => { e.preventDefault(); void run(async () => {
      if (confirm === 'restore') { await fetchApi('/clinic-config/restore', { method: 'POST', body: JSON.stringify({ confirmation: confirmText, name: restoreData ? undefined : restoreName, data: restoreData || undefined }) }); useAccountStore.getState().clear(); setConfirm(null); toast.success('Sauvegarde restaurée. Choisissez un compte.') }
      else { const result = await fetchApi<{ config: ClinicConfig }>('/clinic-config/reset', { method: 'POST', body: JSON.stringify({ confirmation: confirmText }) }); setConfig(result.config); setSaved(structuredClone(result.config)); setSystem(await getClinicSystem()); window.dispatchEvent(new Event('clinic-settings-updated')); setConfirm(null); toast.success('Paramètres réinitialisés') }
    }) }}>{confirm === 'restore' && <><Field label="Sauvegarde locale" value={restoreName} options={[['', 'Choisir une sauvegarde'], ...(system?.backups || []).map(b => [b.name, formatDate(b.created_at)] as [string, string])]} onChange={v => { setRestoreName(v); setRestoreData('') }} /><button type="button" className={secondary} onClick={() => restoreInput.current?.click()}>Importer un fichier .cima</button><input ref={restoreInput} aria-label="Fichier de sauvegarde" className="hidden" type="file" accept=".cima" onChange={e => { const file = e.target.files?.[0]; if (!file) return; if (file.size > 14_000_000) { toast.error('Import limité à 14 Mo. Utilisez la sauvegarde locale pour les fichiers plus grands.'); return } const reader = new FileReader(); reader.onload = () => { setRestoreData(String(reader.result).split(',')[1]); setRestoreName(''); toast.info(`Fichier sélectionné : ${file.name}`) }; reader.readAsDataURL(file) }} /></>}<Field label={`Saisissez ${confirm === 'restore' ? 'RESTAURER' : 'REINITIALISER'} pour confirmer`} value={confirmText} onChange={setConfirmText} /><div className="flex justify-end gap-2"><button type="button" disabled={busy} className={secondary} onClick={() => setConfirm(null)}>Annuler</button><button type="submit" disabled={busy || confirmText !== (confirm === 'restore' ? 'RESTAURER' : 'REINITIALISER') || (confirm === 'restore' && !restoreName && !restoreData)} className={primary}>Confirmer</button></div></form></DialogContent></Dialog>
  </div></BaseLayout>
}
